function calculateBatchTotal(items) {
  let total = 0;
  for (let i = 0; i < items.length; i++) {
    total += items[i].price;
  }
  return total;
}

testCase:
describe('calculateBatchTotal', () => {
  it('should correctly sum prices across all items without throwing TypeError', () => {
    const items = [{ price: 10 }, { price: 20 }, { price: 30 }];
    expect(calculateBatchTotal(items)).toBe(60);
  });
  it('should return 0 for an empty array', () => {
    expect(calculateBatchTotal([])).toBe(0);
  });
});
